INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('12612ba8-e928-40e7-bc06-4d821518ea2c','bbbbbbbb-0001-0000-0000-000000000001',7,'*(ITPAC Porto Nacional)* Atleta: FC repouso **48 bpm**, volume sistólico aumentado. Sedentário: FC **78 bpm**, volume sistólico médio. Professor pede que a turma discuta como o exercício físico crônico influencia o débito cardíaco e seus determinantes.','Qual das alternativas explica corretamente a diferença entre os achados no atleta e no sedentário?','multipla_escolha','O exercício físico crônico promove **bradicardia fisiológica** de repouso (maior tônus vagal e remodelamento cardíaco) e aumento do volume sistólico. O débito cardíaco (DC = VS × FC) se mantém semelhante ao do sedentário em repouso porque o volume sistólico aumentado compensa a FC menor. **Alternativa correta: B.**','GUYTON, A. C.; HALL, J. E. Tratado de Fisiologia Médica. 14ª ed. Elsevier, 2021.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('8bb93b72-2723-45e3-812d-7dfec6ab6e29','12612ba8-e928-40e7-bc06-4d821518ea2c','A','O sedentário mantém débito cardíaco reduzido pois sua FC mais alta não compensa o baixo volume sistólico.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('9d3197bb-a354-499a-8beb-0dc5f7c894a3','12612ba8-e928-40e7-bc06-4d821518ea2c','B','No atleta, o débito cardíaco de repouso é semelhante ao do sedentário, mas o volume sistólico aumentado compensa a FC menor.',true,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('275f62db-2b78-4589-9811-c0e5ff15c9bc','12612ba8-e928-40e7-bc06-4d821518ea2c','C','O atleta apresenta menor débito cardíaco em repouso, já que a FC reduzida não mantém perfusão adequada.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('e17d2776-63d1-4453-a7bf-6d50633cc4f5','12612ba8-e928-40e7-bc06-4d821518ea2c','D','O atleta apresenta maior débito cardíaco em repouso devido à FC reduzida compensada pelo menor volume sistólico.',false,4);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('7ddc72fe-ac05-4448-b4a3-5f36d786bfaf','bbbbbbbb-0001-0000-0000-000000000001',8,'*(AFYA Itacoatiara)* Alunos analisam lâminas HE do tecido cardíaco: fibras estriadas, curtas, ramificadas, núcleos centrais, discos intercalares, vasos no interstício. Professor relaciona as características histológicas à função fisiológica.','Com base nas observações, qual alternativa explica corretamente a importância funcional dessas características?','multipla_escolha','Os **discos intercalares** possuem **junções comunicantes (gap junctions)** e **desmossomos**: as gap junctions permitem transmissão elétrica célula-a-célula; os desmossomos garantem adesão mecânica. Isso faz o miocárdio funcionar como **sincício funcional**, com propagação rápida e coordenada do estímulo para contração rítmica eficiente. **Alternativa correta: D.**','SILVERTHORN, D. U. Fisiologia humana. 7ª ed. Porto Alegre: ArtMed, 2025.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('5d1e2a5c-ab0a-462c-a419-e1e937fdf9ab','7ddc72fe-ac05-4448-b4a3-5f36d786bfaf','A','As fibras cardíacas possuem múltiplos núcleos periféricos, semelhantes ao músculo esquelético, favorecendo contrações voluntárias.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('d7240fc6-818c-44f4-a69f-7e58536f8113','7ddc72fe-ac05-4448-b4a3-5f36d786bfaf','B','A baixa vascularização do miocárdio limita a oferta de O₂, compensada por contração lenta como o músculo liso.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('4067dcaf-3cb3-4a27-b3ff-27be98070c03','7ddc72fe-ac05-4448-b4a3-5f36d786bfaf','C','A origem embrionária no endoderma justifica a presença de fibras musculares lisas no coração.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('6440bbc8-c938-4317-aa8a-cdf4d5df754d','7ddc72fe-ac05-4448-b4a3-5f36d786bfaf','D','A presença dos discos intercalares garante a conexão elétrica e mecânica entre as fibras, permitindo propagação coordenada do estímulo.',true,4);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('c4081b00-e223-4768-83e3-e40b5611b461','bbbbbbbb-0001-0000-0000-000000000001',9,'*(UNIDEP)* Paciente cortado com pedaço de vidro; sangramento diminuiu espontaneamente. Profissional explica os mecanismos de controle hemostático.','Avalie as assertivas e a relação entre elas: **I.** O endotélio íntegro é anticoagulante; quando lesado, expõe colágeno e libera fatores pró-coagulantes. **PORQUE** **II.** O endotélio lesado libera FvW (facilita adesão plaquetária) e reduz PGI₂ e NO, favorecendo agregação plaquetária.','multipla_escolha','**I verdadeira** — duplo papel do endotélio (anticoagulante íntegro / pró-coagulante lesado). **II verdadeira e justifica I** — FvW é pró-coagulante; PGI₂ e NO são anticoagulantes; ambos são alterados na lesão, explicando o mecanismo descrito em I. **Alternativa correta: C.**','HALL, J. E. Guyton & Hall Fundamentos de Fisiologia. 14. ed. Rio de Janeiro: GEN Guanabara Koogan, 2023.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('8260cd7f-b9c0-4dc7-9a5a-7d757a3ae3a7','c4081b00-e223-4768-83e3-e40b5611b461','A','As asserções I e II são verdadeiras, mas a II não justifica a I.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('711175e3-bab0-4d65-befe-235a5c08f2db','c4081b00-e223-4768-83e3-e40b5611b461','B','A assertiva I é verdadeira e a II é falsa.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('145cbf84-6040-46bb-a842-892f66471fce','c4081b00-e223-4768-83e3-e40b5611b461','C','As asserções I e II são verdadeiras e a II justifica a I.',true,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('181e717a-a41e-4bf9-a1e9-dfada29633bc','c4081b00-e223-4768-83e3-e40b5611b461','D','A assertiva I é falsa e a II é verdadeira.',false,4);;
